"""Configuration loading for the core package."""
import json
import os

from cli.args import parse_flags


DEFAULTS = {"workers": 4, "retries": 3}


def load(path):
    """Load a json config file, falling back to DEFAULTS."""
    if not os.path.exists(path):
        return dict(DEFAULTS)
    with open(path, encoding="utf-8") as handle:
        data = json.load(handle)
    merged = dict(DEFAULTS)
    merged.update(data)
    return merged


def override(config, argv):
    """Apply command line overrides to config."""
    flags = parse_flags(argv)
    config.update({k: v for k, v in flags.items() if k in DEFAULTS})
    return config


def describe(config):
    return ", ".join("%s=%s" % item for item in sorted(config.items()))

